var v = value || "";
var m = /(\d{4})年(\d{1,2})月(\d{1,2})日/.exec(v);
if (!m) return "";
var mo = parseInt(m[2], 10);
var dy = parseInt(m[3], 10);
if (mo < 1 || mo > 12 || dy < 1 || dy > 31) return "";
var mm = ("0" + m[2]).slice(-2);
var dd = ("0" + m[3]).slice(-2);
return m[1] + "-" + mm + "-" + dd;

